ALTER TABLE "capital_allocation_target" ADD CONSTRAINT "capital_allocation_target_weights_check" CHECK ("capital_allocation_target"."minimum_weight" between 0 and 1 and "capital_allocation_target"."target_weight" between 0 and 1 and "capital_allocation_target"."maximum_weight" between 0 and 1 and "capital_allocation_target"."minimum_weight" <= "capital_allocation_target"."target_weight" and "capital_allocation_target"."target_weight" <= "capital_allocation_target"."maximum_weight");--> statement-breakpoint
ALTER TABLE "capital_deployment_policy" ADD CONSTRAINT "capital_deployment_policy_values_check" CHECK ("capital_deployment_policy"."monthly_deployment_amount" >= 0 and "capital_deployment_policy"."reserve_floor" >= 0 and "capital_deployment_policy"."fixed_deposit_horizon_days" between 30 and 3650 and "capital_deployment_policy"."transfer_match_window_days" between 0 and 31 and "capital_deployment_policy"."transfer_match_tolerance" between 0 and 1 and char_length("capital_deployment_policy"."deployment_currency") = 3);